// Turkish voice lines (class C). Native script, written from the beat in beats-*.js; never translated from English.
// Group: story-hoods-11-20. beatId -> [{ t, j (joke), spk (only when it differs from the beat) }]. No logic.
Object.assign(P.DLG.tr, {
  "H11b": [{ t: "Kapı kapanmadan kalk abi! Arkaya doğru ilerleyelim! Bozuk yok mu?", ok: 1 }],
  "H11i1a": [{ t: "Aksaray. Dolmuşlar yolda kalmış, farlar hâlâ yanıyor. Trafik hiç bu kadar akmamıştı.", ok: 1 }],
  "H11i2a": [{ t: "Bir korna sesi... Dolmuş geliyor. Bu sefer binmeyeceğim, yemin ederim.", ok: 1 }],
  "H11i3a": [{ t: "Dolmuşçu direksiyonda. Kapı açık, içi karanlık. 'Atla abi, yer var' diye ısrar ediyor.", ok: 1 }],
  "H11p1": [{ t: "Dolmuşların farları hâlâ yanıyor. Sıra sıra dizilmişler, ışıklı bir konvoy gibi.", ok: 1 }],
  "H11p2": [{ t: "Açık kapılı dolmuşa binme. İçinde kim var bilmiyoruz. Ücreti de belli değil.", ok: 1 }],
  "H11p3": [{ t: "Pide fırınının önünden geçiyoruz. Sıcak ekmek kokusu. Bu bir tuzak, biliyorum.", ok: 1 }],
  "H11p4": [{ t: "Ekmek kokusu... Usta'nın ocağı gibi. Bir tane de bana. İki tane. Üç.", ok: 1 }],
  "H12b": [{ t: "Yetişin! Tren gidiyor! İtmeyin! İtin! Kapı kapanıyor!", ok: 1 }],
  "H12i1a": [{ t: "Yenikapı. Metro tünelleri. Işık sadece el fenerinden. Pil de yarı yarıya.", ok: 1 }],
  "H12i2a": [{ t: "Son mesaj, dünden: 'Eve gel. Seni bekliyoruz.' Görüldü. Cevap yazılamadı.", ok: 1 }],
  "H12i3a": [{ t: "Merdivenden iniyorlar. Seslerini duyuyorum. Mesaiden dönüyorlar, hâlâ.", ok: 1 }],
  "H12p1": [{ t: "Fenerin ışığı altı metre. Ötesi zifiri karanlık. Ötesini merak etmiyorum.", ok: 1 }],
  "H12p2": [{ t: "Merdivende sıraya girmişler. Basamağı tut, çıkmasınlar. Ben öndeyim, sen arkamda.", ok: 1 }],
  "H12p3": [{ t: "Telefon titredi! Bir çubuk... sonra hiç. Umut verip kaçtı.", ok: 1 }],
  "H12p4": [{ t: "Tünelde sesler yankılanıyor. Sessiz ol. Nefes de alma. Şaka, al.", ok: 1 }],
  "H13b": [{ t: "Közler hazır! Sıra sende! Az pişmiş mi seversin, çok pişmiş mi?", ok: 1 }],
  "H13i1a": [{ t: "Samatya. Şafak. Yerde battaniyeler, deniz masmavi. Kıyamet sabahları bile güzel.", ok: 1 }],
  "H13i2a": [{ t: "...güvenli bölgelere gidin. Kuzeydeki ormandan uzak durun. Tekrar ediyoruz...", ok: 1 }],
  "H13i3a": [{ t: "Güvenli bölge mi? Hangi taraf? Pusula yok, harita yok, umut yok.", ok: 1 }],
  "H13p1": [{ t: "Battaniyelerin üstünde yarım kalmış bir piknik. Köfteler soğumuş. Yazık.", ok: 1 }],
  "H13p2": [{ t: "Denize itince sürükleniyorlar. Hiç hoş değil ama işe yarıyor. Vicdan sonra.", ok: 1 }],
  "H13p3": [{ t: "Bir kedi tıslıyor. Kediler her şeyi bilir. Bu şehrin asıl sahipleri onlar.", ok: 1 }],
  "H13p4": [{ t: "Mangal dumanı. Biri hâlâ ateş yakıyor. Kıyamet olmuş, mangal bırakılır mı?", ok: 1 }],
  "H14b": [{ t: "Bu kapının anahtarı bende! Yedeği yok! Kopyalatmam!", ok: 1 }],
  "H14i1a": [{ t: "Yedikule surları. Eski kuleler, sarmaşıklar. Bu surlar çok şey gördü, bunu görmedi.", ok: 1 }],
  "H14i2a": [{ t: "Anahtarcı kapıları kilitlemiş. Anahtarlar onda. Kapıcı olsa bu kadar dert çıkmazdı.", ok: 1 }],
  "H14i3a": [{ t: "Anahtarcının halkası her adımda şıngırdıyor. Gizlilik sıfır, özgüven tam.", ok: 1 }],
  "H14p1": [{ t: "Surun üstünde yürüyoruz. Dar ama sağlam. Bin beş yüz yıllık garanti.", ok: 1 }],
  "H14p2": [{ t: "Üç anahtar bulalım, kapıyı açalım. Anahtarcı hepsini saklamış, cimri.", ok: 1 }],
  "H14p3": [{ t: "Çay bahçesinin masaları yolu kesiyor. Çay yok, masa bol. Bu şehrin özeti.", ok: 1 }],
  "H14p4": [{ t: "Sarmaşıkların arkasında bir şey hışırdıyor. Rüzgâr değil. Rüzgâr hırıldamaz.", ok: 1 }],
  "H15b": [{ t: "Su bitmez, asit bitmez! Bahçe sulama saati!", ok: 1 }],
  "H15i1a": [{ t: "Kazlıçeşme. Serin sabah, yeşil çimler, dönen fıskiyeler. Fazla huzurlu.", ok: 1 }],
  "H15i2a": [{ t: "Bu kadar huzur şüpheli. Filmlerde bu sahneden sonra hep biri ölür. Ben olmayayım.", ok: 1 }],
  "H15i3a": [{ t: "Hortumcu asidi uzun hatlarla püskürtüyor. Geriye yakıcı birikintiler kalıyor.", ok: 1 }],
  "H15p1": [{ t: "Fıskiyeler her yeri ıslattı. Hortumcu gelince gözün üstünde olsun.", ok: 1 }],
  "H15p2": [{ t: "Islak zeminde elektrik sıçrıyor. Bekle. Kızarmış Arda kimsenin işine yaramaz.", ok: 1 }],
  "H15p3": [{ t: "Koşucular paket halinde geliyor. Yan yana dur, sırt sırta.", ok: 1 }],
  "H15p4": [{ t: "Dizlerim sızlıyor ama deniz havası iyi geliyor. Yirmi yaşında emekli oldum.", ok: 1 }],
  "H16b": [{ t: "Vardiya bitmedi! Bidonları boşaltın! Mola yok, çay yok!", ok: 1 }],
  "H16i1a": [{ t: "Zeytinburnu. Boya atölyeleri. Renk renk bidonlar, hepsi dolu, hepsi yanıcı.", ok: 1 }],
  "H16i2a": [{ t: "Boyacı Ustası vardiyasını bitirmemiş. Fazla mesai ücretini bizden kesecek.", ok: 1 }],
  "H16i3a": [{ t: "Bidonlar üst üste. Bir kıvılcım, bir zincir, bir de büyük patlama.", ok: 1 }],
  "H16p1": [{ t: "Bir bidon patlarsa hepsi zincirleme patlıyor. Fizik bunu sınavda sormamıştı.", ok: 1 }],
  "H16p2": [{ t: "Yürüyen bant beni itiyor! Kenara çekil! Bant da mesaide, durmuyor!", ok: 1 }],
  "H16p3": [{ t: "Boya kokusu başımı döndürdü. Kaan, sen hep mor muydun?", ok: 1 }],
  "H16p4": [{ t: "Kimse vardiyanın bittiğini söylemiyor. O zaman biz söyleyelim. Paydos!", ok: 1 }],
  "H17b": [{ t: "Zil çaldı! Herkes sınıfa! Koridorda koşan velisini getirsin!", ok: 1 }],
  "H17i1a": [{ t: "Bakırköy Çarşısı. Tavan camından toz sütunları iniyor. Burası hep böyle tozluydu.", ok: 1 }],
  "H17i2a": [{ t: "Dolabım hâlâ orada mı? Şifresini dört yıl çözemedim. Belki kıyamet çözer.", ok: 1 }],
  "H17i3a": [{ t: "Müdür megafonu açtı. Okul zili çalınca dalga gelir. Teneffüs bitti.", ok: 1 }],
  "H17p1": [{ t: "Yürüyen merdiven durmuş. Artık tek yönlü rampa. Geri dönüş yok.", ok: 1 }],
  "H17p2": [{ t: "Okul zili çalıyor. Her çalışta bir dalga geliyor. Lise travmam canlandı.", ok: 1 }],
  "H17p3": [{ t: "Dolapların arasında bir ayakkabı... ve bir defter. Notları da kötüymüş.", ok: 1 }],
  "H17p4": [{ t: "Burası her sabah kalabalıktı. Ben de buradaydım, uykulu ve geç.", ok: 1 }],
  "H18b": [{ t: "Bir kaşık daha? Bedava, bedava! Külahı tut! Tutamadın! Bir daha!", ok: 1 }],
  "H18i1a": [{ t: "Bakırköy sahili. Palmiyeler, bisiklet yolu ve zilini çalan bir dondurmacı arabası.", ok: 1 }],
  "H18i2a": [{ t: "Bir keresinde bana bedava dondurma vermişti. Üç kez geri çekerek. Bir kepçe borcum var.", ok: 1 }],
  "H18i3a": [{ t: "Arabanın çanı çalıyor. Her çalışta yeni bir dalga. Dondurma ise hiç erimiyor.", ok: 1 }],
  "H18p1": [{ t: "Dondurma arabası! Zil çalınca hemen kaç. Dondurma için ölünmez.", ok: 1 }],
  "H18p2": [{ t: "Bisiklet yolundan geliyorlar. Ters yönden! Ölmüşler ama kural tanımıyorlar.", ok: 1 }],
  "H18p3": [{ t: "Sahilde artık kimse yüzmüyor. Denizanaları bile tatile çıkmış.", ok: 1 }],
  "H18p4": [{ t: "Çocukluğumun sahili. Aynı palmiyeler, aynı banklar. Sadece çok sessiz.", ok: 1 }],
  "H19b": [{ t: "Bu rıhtım benim! Herkesi bağlarım! Özel mülk, zombiler dahil!", ok: 1 }],
  "H19i1a": [{ t: "Ataköy Marina. Direkler arasında gün doğuyor. Eve bir kilometre. Sadece bir.", ok: 1 }],
  "H19i2a": [{ t: "Mahalleni biliyorum demiştin. Hadi göster. Kaybolursak senin suçun.", ok: 1 }],
  "H19i2b": [{ t: "Ahmet Abi'nin ekmeği burada. Biraz bayat. Kalkan gibi sert. Yine de yerim.", ok: 1 }],
  "H19i3a": [{ t: "Yat sahibi. Rıhtımda zincir sallanıyor. Denizciler uyanıyor. Tayfası hâlâ sadık.", ok: 1 }],
  "H19p1": [{ t: "Pontonlar sallanıyor. Dengeni koru. Denize düşeni kimse çıkarmaz, bilgin olsun.", ok: 1 }],
  "H19p2": [{ t: "Halatlar ağ gibi. Zombiler takılıp kalıyor. Gizli balıkçılık yeteneğim ortaya çıktı.", ok: 1 }],
  "H19p3": [{ t: "Denizciler çıkıyor. Hepsi uyandı mı? Kaptanım da aralarında mı acaba?", ok: 1 }],
  "H19p4": [{ t: "Eve bir kilometre. Sen de gel Kaan. Annem seni de doyurur.", ok: 1 }],
  "H20b": [{ t: "Ekmek al, yavrum. Mont da giy. Sonra beni affedersin.", ok: 1 }],
  "H20i1a": [{ t: "Ataköy. Bej binalar, mavi panjurlar, balkonlarda çamaşır ipleri. Ev.", ok: 1 }],
  "H20i2a": [{ t: "Fırın kokusu... Ahmet Abi her sabah buradaydı. 'Yavrum, mont giy' derdi. Giymezdim.", ok: 1 }],
  "H20i3a": [{ t: "Kapıcı kulübesinde biri var. Kapı aralık. Kimse selam vermiyor.", ok: 1 }],
  "H20p1": [{ t: "Ahmet Abi'nin ekmek sepeti... Kalkan olabilir. Önce bir ekmek alayım ama.", ok: 1 }],
  "H20p2": [{ t: "Kapıcı kulübesinin anahtarı nerede? Ahmet Abi hep paspasın altına koyardı.", ok: 1 }],
  "H20p3": [{ t: "Çamaşır ipleri arasında biri zıplıyor. Teyzenin çarşafları gitti.", ok: 1 }],
  "H20p4": [{ t: "Apartmanın kapısı açık. İçeriden bir ses geliyor. Lütfen annem olsun.", ok: 1 }],
});
